function calcAngle(anglesWithOffsets) {
    function toRealAngle(offset, x) {
        return (((x + 360) % 360) + offset) % 360;
    }

    function deltaAngle(x, y) {
        return 180 - Math.abs(Math.abs(x - y) - 180);
    }

    let sorted = anglesWithOffsets
        .sort((x, y) => deltaAngle(x.angle, 90) - deltaAngle(y.angle, 90))
        .slice(0, -1);
    let real = sorted.map((x) => [
        { offset: x.offset, angle: x.angle, real: toRealAngle(x.offset, x.angle) },
        {
            offset: x.offset,
            angle: -x.angle,
            real: toRealAngle(x.offset, -x.angle),
        },
    ]);
    let [best, second] = real;
    let deltas = best.map((x) =>
        Math.min(
            deltaAngle(x.real, second[0].real),
            deltaAngle(x.real, second[1].real)
        )
    );
    let result = deltas[0] < deltas[1] ? best[0].real : best[1].real;
    //console.log("CA:", [sorted[0].index, sorted[1].index, result]);
    return result;
}

